import{_ as l,r as t,o as u,c as i,e as p,a as n,s as e,d as s}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"事件处理程序 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"AJAX 处理程序","slug":"ajax-处理程序","link":"#ajax-处理程序","children":[{"level":3,"title":"调用处理程序","slug":"调用处理程序","link":"#调用处理程序","children":[{"level":4,"title":"通用处理程序","slug":"通用处理程序","link":"#通用处理程序","children":[]}]}]},{"level":2,"title":"AJAX 处理程序中的重定向","slug":"ajax-处理程序中的重定向","link":"#ajax-处理程序中的重定向","children":[]},{"level":2,"title":"从 AJAX 处理程序返回数据","slug":"从-ajax-处理程序返回数据","link":"#从-ajax-处理程序返回数据","children":[]},{"level":2,"title":"抛出 AJAX 异常","slug":"抛出-ajax-异常","link":"#抛出-ajax-异常","children":[]},{"level":2,"title":"在处理程序之前运行代码","slug":"在处理程序之前运行代码","link":"#在处理程序之前运行代码","children":[]}],"relativePath":"2.x/zh-cn/ajax/handlers.md","filePath":"2.x/zh-cn/ajax/handlers.md"}'),r={name:"2.x/zh-cn/ajax/handlers.md"};function k(d,a,g,h,m,f){const o=t("pre-heading"),c=t("post-heading");return u(),i("div",null,[p(o),a[0]||(a[0]=n("h1",null,"事件处理程序",-1)),p(c),a[1]||(a[1]=e(`<h2 id="ajax-处理程序"><a href="#ajax-处理程序" class="header-anchor">#</a> AJAX 处理程序</h2><p>AJAX 事件处理程序是 PHP 函数，可以在页面或布局 <a href="./../cms/themes.html#oc-php-section">PHP 部分</a> 或 <a href="./../cms/components.html">组件</a> 内部定义。 处理程序名称应具有以下模式：<code>onName</code>。 所有处理程序都支持使用 <a href="./../ajax/update-partials.html">更新部分</a> 作为 AJAX 请求的一部分。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSubmitContactForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果在一个页面和布局中一起定义了两个同名的处理程序，则页面处理程序将被执行。 <a href="./../cms/components.html">components</a> 中定义的处理程序具有最低优先级。</p><p><a id="oc-calling-a-handler"></a></p><h3 id="调用处理程序"><a href="#调用处理程序" class="header-anchor">#</a> 调用处理程序</h3><p>每个 AJAX 请求都应使用 <a href="./../ajax/attributes-api.html">数据属性 API</a> 或 <a href="./../ajax/javascript-api.html">JavaScript API</a> 指定处理程序名称。 发出请求后，服务器将搜索所有已注册的处理程序并定位它找到的第一个处理程序。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- 数据属性 API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmitContactForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Go<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token comment">&lt;!-- JavaScript API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"> $<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onSubmitContactForm&#39;</span><span class="token punctuation">)</span> </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>如果两个组件注册了相同的处理程序名称，建议使用 <a href="./../cms/components.html#oc-components-aliases">组件短名称或别名</a> 作为处理程序的前缀。如果组件使用 <strong>mycomponent</strong> 的别名，则可以使用 <code>mycomponent::onName</code> 来定位处理程序。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mycomponent::onSubmitContactForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Go<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div>`,10)),a[2]||(a[2]=n("p",null,[s("您可能希望使用 "),n("a",{href:"https://octobercms.com/docs/plugin/components#referencing-self",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("code",null,"__SELF__"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),n("span",{class:"sr-only"},"(opens new window)")])]),s(" 引用变量而不是写死别名，以防用户更改页面上使用的组件别名.")],-1)),a[3]||(a[3]=e(`<div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{{ __SELF__ }}::onCalculate<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token punctuation">&#39;</span>{{ __SELF__ }}::calcresult&#39;: &#39;#result&#39;<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="通用处理程序"><a href="#通用处理程序" class="header-anchor">#</a> 通用处理程序</h4><p>有时您可能需要仅出于更新页面内容的目的而发出 AJAX 请求，而不需要执行任何代码。为此，您可以使用 <code>onAjax</code> 处理程序。此处理程序随处可用，无需编写任何代码。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>啥都不做<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="ajax-处理程序中的重定向"><a href="#ajax-处理程序中的重定向" class="header-anchor">#</a> AJAX 处理程序中的重定向</h2><p>如果您需要将浏览器重定向到另一个位置，请从 AJAX 处理程序返回 <code>Redirect</code> 对象。一旦从服务器返回响应，框架将重定向浏览器。示例 AJAX 处理程序：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirectMe</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;http://www.huawei.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="从-ajax-处理程序返回数据"><a href="#从-ajax-处理程序返回数据" class="header-anchor">#</a> 从 AJAX 处理程序返回数据</h2><p>在高级情况下，您可能希望从 AJAX 处理程序返回结构化数据。如果 AJAX 处理程序返回一个数组，您可以在 <code>success</code> 事件处理程序中访问它的元素。示例 AJAX 处理程序：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onFetchDataFromServer</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">/* 一些服务器端代码 */</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;totalUsers&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1000</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;totalProjects&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">937</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>可以使用数据属性 API 获取数据：</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onHandleForm<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-success</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>console.log(data)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>与 JavaScript API 相同：</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
    <span class="token special-attr"><span class="token attr-name">onsubmit</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value javascript language-javascript"><span class="token function">$</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onHandleForm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
        <span class="token function-variable function">success</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span><span class="token punctuation">&quot;</span></span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="抛出-ajax-异常"><a href="#抛出-ajax-异常" class="header-anchor">#</a> 抛出 AJAX 异常</h2><p>您可以使用 <code>AjaxException</code> 类抛出 <a href="./../services/error-log.html#oc-ajax-exception">AJAX 异常</a> 将响应视为错误，同时保留正常发送响应内容的能力。只需将响应内容作为异常的第一个参数传递。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">AjaxException</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;error&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;错误提示&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;questionsNeeded&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">2</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：当抛出这个异常类型时 <a href="./../ajax/update-partials.html">部件将被更新</a> 正常。</p></blockquote><h2 id="在处理程序之前运行代码"><a href="#在处理程序之前运行代码" class="header-anchor">#</a> 在处理程序之前运行代码</h2><p>有时您可能希望在处理程序执行之前执行代码。将 <code>onInit</code> 函数定义为 <a href="./../cms/layouts.html#oc-dynamic-layouts">页面执行生命周期</a> 的一部分，允许代码在每个 AJAX 处理程序之前运行。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onInit</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 页面或布局 PHP 代码部分</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您可以在 <a href="./../plugin/components.html#oc-component-initialization">组件类</a> 或 <a href="./../backend/widgets.html">后端小部件类</a> 中定义一个 <code>init</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 组件或小部件类</span>
<span class="token punctuation">}</span>
</code></pre></div>`,23))])}const A=l(r,[["render",k]]);export{x as __pageData,A as default};
